const f=await glob({pattern:"data/orders/*.json"});
const rep={changed:[],skipped:[],odd:[]};
for(const p of f.files){
 const raw=(await read({path:p})).content;
 const o=JSON.parse(raw);
 if(o.status!=="paid"){ if(String(o.status).toLowerCase().trim()==="paid") rep.odd.push([p,o.status]); rep.skipped.push(o.status); continue;}
 if(!Array.isArray(o.items)||o.items.some(i=>typeof i.qty!=="number")){rep.odd.push([p,"bad items"]);continue;}
 o.itemCount=o.items.reduce((s,i)=>s+i.qty,0);
 const nl=raw.endsWith("\n")?"\n":"";
 await write({path:p,content:JSON.stringify(o,null,2)+nl});
 rep.changed.push(o.itemCount);
}
rep.skipped=[...new Set(rep.skipped)];
return rep;

